if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
    usage
    exit 0
fi

SERVER_BIN="${SERVER_BIN:-./build/bin/llama-server}"
MODEL="${MODEL:-unsloth/Qwen3.6-35B-A3B-GGUF:Q8_0}"
HOST="${HOST:-0.0.0.0}"
PORT="${PORT:-8033}"
SERVER_URL="${SERVER_URL:-http://127.0.0.1:${PORT}}"
N_PREDICT="${N_PREDICT:-256}"
START_SERVER="${START_SERVER:-1}"
SAVE_RESPONSE="${SAVE_RESPONSE:-0}"
EXTRA_SERVER_ARGS="${EXTRA_SERVER_ARGS:-}"

if [[ "${START_SERVER}" == "1" ]]; then
    export GGML_GFX906_TRACE="${GGML_GFX906_TRACE:-1}"
else
    GGML_GFX906_TRACE="${GGML_GFX906_TRACE:-0}"
fi

if [[ "${START_SERVER}" == "1" && ! -x "${SERVER_BIN}" ]]; then
    echo "server binary is not executable: ${SERVER_BIN}" >&2
    exit 2
fi

if [[ "${START_SERVER}" == "1" && "${GGML_GFX906_TRACE}" != "0" ]]; then
    TRACE_LIB="$(ldd "${SERVER_BIN}" 2>/dev/null | awk '/libggml-hip\.so/ { print $3; exit }')"
    if [[ -n "${TRACE_LIB}" && -r "${TRACE_LIB}" ]] && ! grep -a -q 'gfx906_trace: %s' "${TRACE_LIB}"; then
        echo "GGML_GFX906_TRACE is enabled, but the linked libggml-hip does not contain gfx906 tracing." >&2
        echo "Rebuild llama-server, then run this profiler again." >&2
        exit 2
    fi
fi

PROMPT_ARG="${1:-}"
RUN_DIR="${2:-profiles/gfx906-$(date +%Y%m%d-%H%M%S)}"
mkdir -p "${RUN_DIR}"

if [[ -n "${PROMPT_ARG}" ]]; then
    PROMPT_FILE="${PROMPT_ARG}"
    if [[ ! -f "${PROMPT_FILE}" ]]; then
        echo "prompt file not found: ${PROMPT_FILE}" >&2
        exit 2
    fi
else
    PROMPT_FILE="${RUN_DIR}/embedded-prompt.txt"
    embedded_prompt >"${PROMPT_FILE}"
    if grep -qx 'PASTE_DEINEN_110K_PROMPT_HIER_REIN' "${PROMPT_FILE}"; then
        echo "embedded prompt is still empty. Edit embedded_prompt() in scripts/gfx906-profile-server.sh first." >&2
        exit 2
    fi
fi

SERVER_LOG="${RUN_DIR}/server.log"
FILTERED_LOG="${RUN_DIR}/server.filtered.log"
CLIENT_JSON="${RUN_DIR}/client.json"
TIMINGS_JSON="${RUN_DIR}/timings.json"
REPORT="${RUN_DIR}/report.txt"

SERVER_PID=""
cleanup() {
    if [[ -n "${SERVER_PID}" ]] && kill -0 "${SERVER_PID}" 2>/dev/null; then
        kill "${SERVER_PID}" 2>/dev/null || true
        wait "${SERVER_PID}" 2>/dev/null || true
    fi
}
trap cleanup EXIT

export LD_LIBRARY_PATH="/opt/rocm/lib:${LD_LIBRARY_PATH:-}"
export LIBRARY_PATH="/opt/rocm/lib:${LIBRARY_PATH:-}"

server_cmd=(
    "${SERVER_BIN}"
    -hf "${MODEL}"
    --jinja
    --host "${HOST}"
    --port "${PORT}"
    -ngl 999
    -c 128000
    -np 2
    -fa on
    -sm layer
    -b 512
    -ub 256
    --cache-type-k q8_0
    --cache-type-v q8_0
    --no-mmap
    --repeat-penalty 1.05
    --kv-unified
    --cont-batching
)

if [[ -n "${EXTRA_SERVER_ARGS}" ]]; then
    # shellcheck disable=SC2206
    extra_args=( ${EXTRA_SERVER_ARGS} )
    server_cmd+=( "${extra_args[@]}" )
fi

if [[ "${START_SERVER}" == "1" ]]; then
    if python3 - "$PORT" <<'PY'
import socket
import sys

port = int(sys.argv[1])
with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
    sock.settimeout(0.5)
    sys.exit(0 if sock.connect_ex(("127.0.0.1", port)) == 0 else 1)
PY
    then
        echo "port ${PORT} is already in use. Stop the old server or set PORT=another_port." >&2
        exit 2
    fi

    echo "starting llama-server, log: ${SERVER_LOG}"
    "${server_cmd[@]}" >"${SERVER_LOG}" 2>&1 &
    SERVER_PID="$!"
    sleep 2
    if ! kill -0 "${SERVER_PID}" 2>/dev/null; then
        echo "llama-server exited before becoming healthy. Last log lines:" >&2
        tail -n 80 "${SERVER_LOG}" >&2 || true
        exit 1
    fi
else
    echo "START_SERVER=0: using existing server at ${SERVER_URL}"
    : >"${SERVER_LOG}"
fi

python3 - "$SERVER_URL" "$PROMPT_FILE" "$N_PREDICT" "$CLIENT_JSON" "$TIMINGS_JSON" "$SAVE_RESPONSE" <<'PY'
import json
import os
import sys
import time
import urllib.error
import urllib.request

base = sys.argv[1].rstrip("/")
prompt_file = sys.argv[2]
n_predict = int(sys.argv[3])
client_json = sys.argv[4]
timings_json = sys.argv[5]
save_response = sys.argv[6] == "1"

def request_json(method, path, data=None, timeout=10):
    body = None
    headers = {}
    if data is not None:
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(base + path, data=body, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="replace")
        return json.loads(raw) if raw else {}

deadline = time.time() + 1800
last_error = None
while time.time() < deadline:
    try:
        health = request_json("GET", "/health", timeout=5)
        status = health.get("status")
        if status in ("ok", "idle", "ready") or health:
            break
    except Exception as exc:
        last_error = repr(exc)
    time.sleep(2)
else:
    raise SystemExit(f"server did not become healthy; last error: {last_error}")

with open(prompt_file, "r", encoding="utf-8", errors="replace") as f:
    prompt = f.read()

payload = {
    "messages": [
        {"role": "user", "content": prompt},
    ],
    "max_tokens": n_predict,
    "temperature": 0,
    "stream": True,
    "timings_per_token": True,
}

req = urllib.request.Request(
    base + "/v1/chat/completions",
    data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
    headers={"Content-Type": "application/json"},
    method="POST",
)

t0 = time.time()
first_chunk_s = None
first_content_s = None
last_timings = None
chunks = 0
content_parts = []
errors = []

try:
    with urllib.request.urlopen(req, timeout=7200) as resp:
        for raw_line in resp:
            line = raw_line.decode("utf-8", errors="replace").strip()
            if not line:
                continue
            if not line.startswith("data:"):
                continue
            data = line[5:].strip()
            if data == "[DONE]":
                break
            chunks += 1
            if first_chunk_s is None:
                first_chunk_s = time.time() - t0
            try:
                obj = json.loads(data)
            except json.JSONDecodeError as exc:
                errors.append(f"json decode error: {exc}: {data[:200]}")
                continue
            timings = obj.get("timings")
            if timings:
                last_timings = timings
            choices = obj.get("choices") or []
            for choice in choices:
                delta = choice.get("delta") or {}
                text = delta.get("content") or ""
                if text:
                    if first_content_s is None:
                        first_content_s = time.time() - t0
                    if save_response:
                        content_parts.append(text)
except urllib.error.HTTPError as exc:
    body = exc.read().decode("utf-8", errors="replace")
    raise SystemExit(f"HTTP {exc.code}: {body[:2000]}")

t1 = time.time()
prompt_bytes = os.path.getsize(prompt_file)
result = {
    "prompt_file": os.path.abspath(prompt_file),
    "prompt_bytes": prompt_bytes,
    "n_predict_requested": n_predict,
    "wall_seconds": t1 - t0,
    "first_sse_chunk_seconds": first_chunk_s,
    "first_content_seconds": first_content_s,
    "sse_chunks": chunks,
    "timings": last_timings or {},
    "errors": errors,
}
if save_response:
    result["response_text"] = "".join(content_parts)

with open(client_json, "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
with open(timings_json, "w", encoding="utf-8") as f:
    json.dump(last_timings or {}, f, ensure_ascii=False, indent=2)

print(json.dumps(result, ensure_ascii=False, indent=2))
PY

grep -Ei \
    'gfx906|GFX906|HIP|ROCm|rocBLAS|hipBLAS|offload|flash|fattn|MMQ|MMVQ|mul_mat|MUL_MAT|MUL_MAT_ID|prompt eval|eval time|tokens per second|CUDA graph|graph|SOLVE_TRI|slot|timings|cache|KV' \
    "${SERVER_LOG}" >"${FILTERED_LOG}" || true

{
    echo "gfx906 profile report"
    echo "====================="
    echo
    echo "date: $(date -Is)"
    echo "repo: $(pwd)"
    echo "git: $(git rev-parse --short HEAD 2>/dev/null || true)"
    echo "prompt_file: $(realpath "${PROMPT_FILE}")"
    echo "prompt_bytes: $(wc -c < "${PROMPT_FILE}")"
    echo "server_bin: ${SERVER_BIN}"
    echo "model: ${MODEL}"
    echo "server_url: ${SERVER_URL}"
    echo "port: ${PORT}"
    echo "n_predict: ${N_PREDICT}"
    echo "GGML_GFX906_TRACE: ${GGML_GFX906_TRACE:-0}"
    echo
    echo "rocm:"
    if command -v /opt/rocm/bin/hipconfig >/dev/null 2>&1; then
        /opt/rocm/bin/hipconfig --version || true
    elif command -v hipconfig >/dev/null 2>&1; then
        hipconfig --version || true
    else
        echo "hipconfig not found"
    fi
    echo
    echo "binary links:"
    ldd "${SERVER_BIN}" 2>/dev/null | grep -Ei 'hip|roc|hsa|blas|ggml-hip' || true
    echo
    echo "client timings:"
    python3 - "$CLIENT_JSON" <<'PY'
import json, sys
with open(sys.argv[1], encoding="utf-8") as f:
    data = json.load(f)
t = data.get("timings") or {}
for key in [
    "prompt_n", "prompt_ms", "prompt_per_token_ms", "prompt_per_second",
    "predicted_n", "predicted_ms", "predicted_per_token_ms", "predicted_per_second",
    "cache_n",
]:
    print(f"{key}: {t.get(key)}")
print(f"wall_seconds: {data.get('wall_seconds')}")
print(f"first_sse_chunk_seconds: {data.get('first_sse_chunk_seconds')}")
print(f"first_content_seconds: {data.get('first_content_seconds')}")
print(f"sse_chunks: {data.get('sse_chunks')}")
if data.get("errors"):
    print("errors:")
    for err in data["errors"]:
        print(f"  {err}")
PY
    echo
    echo "relevant server log tail:"
    tail -n 200 "${FILTERED_LOG}" || true
    echo
    echo "files:"
    echo "  report: ${REPORT}"
    echo "  timings: ${TIMINGS_JSON}"
    echo "  client: ${CLIENT_JSON}"
    echo "  server_log: ${SERVER_LOG}"
    echo "  filtered_log: ${FILTERED_LOG}"
} | tee "${REPORT}"

echo
echo "done: ${REPORT}"
